cssCode:
.vid-scroll-wrap {
  height: 400vh; /* સ્ક્રોલ કરવા માટે ખૂબ લાંબી જગ્યા */
  width: 100%;
  position: relative;
  background: #000;
}
.vid-sticky-box {
  position: sticky;
  top: 0;
  height: 100vh;
  width: 100%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.scroll-video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.8;
}
.vid-text-overlay {
  position: absolute;
  color: #fff;
  font-family: sans-serif;
  font-size: 40px;
  font-weight: 900;
  text-shadow: 0 5px 15px rgba(0,0,0,0.8);
  transition: opacity 0.2s, transform 0.2s;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000;';

const wrap = document.createElement('div');
wrap.className = 'vid-scroll-wrap';

const stickyBox = document.createElement('div');
stickyBox.className = 'vid-sticky-box';

// અહી તમે તમારો કોઈપણ વિડીયો લિંક મૂકી શકો છો
const video = document.createElement('video');
video.className = 'scroll-video';
video.src = 'https://www.w3schools.com/html/mov_bbb.mp4'; 
video.muted = true;
video.playsInline = true;
video.pause();

const textEl = document.createElement('div');
textEl.className = 'vid-text-overlay';
textEl.innerText = 'SCROLL TO PLAY';

stickyBox.appendChild(video);
stickyBox.appendChild(textEl);
wrap.appendChild(stickyBox);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const progress = c.scrollTop / maxScroll;

  // વિડીયોને સ્ક્રોલ સાથે પ્લે કરવો
  if (video.duration) {
    video.currentTime = progress * video.duration;
  }

  // લખાણને સ્ક્રોલ સાથે ઝૂમ અને ફેડ કરવું
  if (progress > 0.1 && progress < 0.8) {
    textEl.style.transform = `scale(${1 + progress * 2})`;
    textEl.style.opacity = 1 - (progress * 1.5);
  } else if (progress >= 0.8) {
    textEl.style.opacity = 0;
  } else {
    textEl.style.transform = 'scale(1)';
    textEl.style.opacity = 1;
  }
});
